head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil15801";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil15801.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "img_49", fn: function(){ return ((dma_krpReport.get("fileSurFix") ?? (() => { throw new Error("unresolved:" + "krpReport.fileSurFix"); })()) === 'HWP'); } }, { id: "txt_text50", fn: function(){ return ((dma_krpReport.get("fileSurFix") ?? (() => { throw new Error("unresolved:" + "krpReport.fileSurFix"); })()) === 'HWP'); } }, { id: "img_52", fn: function(){ return ((dma_krpReport.get("fileSurFix") ?? (() => { throw new Error("unresolved:" + "krpReport.fileSurFix"); })()) === 'XLS'); } }, { id: "txt_text53", fn: function(){ return ((dma_krpReport.get("fileSurFix") ?? (() => { throw new Error("unresolved:" + "krpReport.fileSurFix"); })()) === 'XLS'); } }, { id: "img_55", fn: function(){ return ((dma_krpReport.get("fileSurFix") ?? (() => { throw new Error("unresolved:" + "krpReport.fileSurFix"); })()) === 'DOC'); } }, { id: "txt_text56", fn: function(){ return ((dma_krpReport.get("fileSurFix") ?? (() => { throw new Error("unresolved:" + "krpReport.fileSurFix"); })()) === 'DOC'); } }, { id: "img_58", fn: function(){ return ((dma_krpReport.get("fileSurFix") ?? (() => { throw new Error("unresolved:" + "krpReport.fileSurFix"); })()) === 'PPT'); } }, { id: "txt_text59", fn: function(){ return ((dma_krpReport.get("fileSurFix") ?? (() => { throw new Error("unresolved:" + "krpReport.fileSurFix"); })()) === 'PPT'); } }, { id: "img_61", fn: function(){ return ((dma_krpReport.get("fileSurFix") ?? (() => { throw new Error("unresolved:" + "krpReport.fileSurFix"); })()) === 'PDF'); } }, { id: "txt_text62", fn: function(){ return ((dma_krpReport.get("fileSurFix") ?? (() => { throw new Error("unresolved:" + "krpReport.fileSurFix"); })()) === 'PDF'); } }, { id: "c_otherwise_63", fn: function(){ return (!(((dma_krpReport.get("fileSurFix") ?? (() => { throw new Error("unresolved:" + "krpReport.fileSurFix"); })()) === 'HWP') || ((dma_krpReport.get("fileSurFix") ?? (() => { throw new Error("unresolved:" + "krpReport.fileSurFix"); })()) === 'XLS') || ((dma_krpReport.get("fileSurFix") ?? (() => { throw new Error("unresolved:" + "krpReport.fileSurFix"); })()) === 'DOC') || ((dma_krpReport.get("fileSurFix") ?? (() => { throw new Error("unresolved:" + "krpReport.fileSurFix"); })()) === 'PPT') || ((dma_krpReport.get("fileSurFix") ?? (() => { throw new Error("unresolved:" + "krpReport.fileSurFix"); })()) === 'PDF'))); } }, { id: "if_fileSurFix", fn: function(){ return (!(String(((dma_krpReport.get("fileSurFix") ?? (() => { throw new Error("unresolved:" + "krpReport.fileSurFix"); })())) == null ? '' : ((dma_krpReport.get("fileSurFix") ?? (() => { throw new Error("unresolved:" + "krpReport.fileSurFix"); })()))).length === 0) && (dma_krpReport.get("fileSurFix") ?? (() => { throw new Error("unresolved:" + "krpReport.fileSurFix"); })()) !== ''); } }, { id: "c_when_78", fn: function(){ return (!(String(((dma_krpReport.get("nextKrpReport") ?? (() => { throw new Error("unresolved:" + "krpReport.nextKrpReport"); })())) == null ? '' : ((dma_krpReport.get("nextKrpReport") ?? (() => { throw new Error("unresolved:" + "krpReport.nextKrpReport"); })()))).length === 0)); } }, { id: "c_otherwise_82", fn: function(){ return (!((!(String(((dma_krpReport.get("nextKrpReport") ?? (() => { throw new Error("unresolved:" + "krpReport.nextKrpReport"); })())) == null ? '' : ((dma_krpReport.get("nextKrpReport") ?? (() => { throw new Error("unresolved:" + "krpReport.nextKrpReport"); })()))).length === 0)))); } }, { id: "c_when_90", fn: function(){ return (!(String(((dma_krpReport.get("preKrpReport") ?? (() => { throw new Error("unresolved:" + "krpReport.preKrpReport"); })())) == null ? '' : ((dma_krpReport.get("preKrpReport") ?? (() => { throw new Error("unresolved:" + "krpReport.preKrpReport"); })()))).length === 0)); } }, { id: "c_otherwise_94", fn: function(){ return (!((!(String(((dma_krpReport.get("preKrpReport") ?? (() => { throw new Error("unresolved:" + "krpReport.preKrpReport"); })())) == null ? '' : ((dma_krpReport.get("preKrpReport") ?? (() => { throw new Error("unresolved:" + "krpReport.preKrpReport"); })()))).length === 0)))); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_DownKrpFile_onclick
 * @description btn_DownKrpFile 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_DownKrpFile_onclick = async function(e){
    try {
        await scwin.downKrpFile('' + dma_krpReport.get("realName") + '','' + dma_krpReport.get("fileName") + '','' + dma_krpReport.get("fileDir") + '')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil15801.btn_DownKrpFile_onclick' }); }
};

/**
 * @method
 * @name btn_GoURL_onclick
 * @description btn_GoURL 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_GoURL_onclick = async function(e){
    try {
        await scwin.goURL('list')
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldfil15801.btn_GoURL_onclick" });
    }
};

