 * @hidden N
 */
scwin.btn_GoURL_2_onclick = async function(e){
    try {
        await scwin.goURL('detail',(String(((dma_krpReport.get("isuSrtCd") ?? (() => { throw new Error("unresolved:" + "krpReport.nextKrpReport.isuSrtCd"); })())) == null ? '' : ((dma_krpReport.get("isuSrtCd") ?? (() => { throw new Error("unresolved:" + "krpReport.nextKrpReport.isuSrtCd"); })()))).indexOf('$' + '{') >= 0 ? '' : String(((dma_krpReport.get("isuSrtCd") ?? (() => { throw new Error("unresolved:" + "krpReport.nextKrpReport.isuSrtCd"); })())) == null ? '' : ((dma_krpReport.get("isuSrtCd") ?? (() => { throw new Error("unresolved:" + "krpReport.nextKrpReport.isuSrtCd"); })())))),(String(((dma_krpReport.get("bycorpSeq") ?? (() => { throw new Error("unresolved:" + "krpReport.nextKrpReport.bycorpSeq"); })())) == null ? '' : ((dma_krpReport.get("bycorpSeq") ?? (() => { throw new Error("unresolved:" + "krpReport.nextKrpReport.bycorpSeq"); })()))).indexOf('$' + '{') >= 0 ? '' : String(((dma_krpReport.get("bycorpSeq") ?? (() => { throw new Error("unresolved:" + "krpReport.nextKrpReport.bycorpSeq"); })())) == null ? '' : ((dma_krpReport.get("bycorpSeq") ?? (() => { throw new Error("unresolved:" + "krpReport.nextKrpReport.bycorpSeq"); })())))),(String(((dma_krpReport.get("partcYy") ?? (() => { throw new Error("unresolved:" + "krpReport.nextKrpReport.partcYy"); })())) == null ? '' : ((dma_krpReport.get("partcYy") ?? (() => { throw new Error("unresolved:" + "krpReport.nextKrpReport.partcYy"); })()))).indexOf('$' + '{') >= 0 ? '' : String(((dma_krpReport.get("partcYy") ?? (() => { throw new Error("unresolved:" + "krpReport.nextKrpReport.partcYy"); })())) == null ? '' : ((dma_krpReport.get("partcYy") ?? (() => { throw new Error("unresolved:" + "krpReport.nextKrpReport.partcYy"); })())))))

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil15801.btn_GoURL_2_onclick' }); }
};

/**
