        await scwin.goURL('detail',(String(((dma_krpReport.get("isuSrtCd") ?? (() => { throw new Error("unresolved:" + "krpReport.preKrpReport.isuSrtCd"); })())) == null ? '' : ((dma_krpReport.get("isuSrtCd") ?? (() => { throw new Error("unresolved:" + "krpReport.preKrpReport.isuSrtCd"); })()))).indexOf('$' + '{') >= 0 ? '' : String(((dma_krpReport.get("isuSrtCd") ?? (() => { throw new Error("unresolved:" + "krpReport.preKrpReport.isuSrtCd"); })())) == null ? '' : ((dma_krpReport.get("isuSrtCd") ?? (() => { throw new Error("unresolved:" + "krpReport.preKrpReport.isuSrtCd"); })())))),(String(((dma_krpReport.get("bycorpSeq") ?? (() => { throw new Error("unresolved:" + "krpReport.preKrpReport.bycorpSeq"); })())) == null ? '' : ((dma_krpReport.get("bycorpSeq") ?? (() => { throw new Error("unresolved:" + "krpReport.preKrpReport.bycorpSeq"); })()))).indexOf('$' + '{') >= 0 ? '' : String(((dma_krpReport.get("bycorpSeq") ?? (() => { throw new Error("unresolved:" + "krpReport.preKrpReport.bycorpSeq"); })())) == null ? '' : ((dma_krpReport.get("bycorpSeq") ?? (() => { throw new Error("unresolved:" + "krpReport.preKrpReport.bycorpSeq"); })())))),(String(((dma_krpReport.get("partcYy") ?? (() => { throw new Error("unresolved:" + "krpReport.preKrpReport.partcYy"); })())) == null ? '' : ((dma_krpReport.get("partcYy") ?? (() => { throw new Error("unresolved:" + "krpReport.preKrpReport.partcYy"); })()))).indexOf('$' + '{') >= 0 ? '' : String(((dma_krpReport.get("partcYy") ?? (() => { throw new Error("unresolved:" + "krpReport.preKrpReport.partcYy"); })())) == null ? '' : ((dma_krpReport.get("partcYy") ?? (() => { throw new Error("unresolved:" + "krpReport.preKrpReport.partcYy"); })())))))

