///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_fn_GoURL
 * @description Go URL 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_GoURL = async function (action) {
    try { return await $c.data.downFile(action ?? "/support/report.do", "", ($c.util.getComponent("dma_GoURLReq") ? $c.util.getComponent("dma_GoURLReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name tx_fn_DownKrpFile
 * @description Down Krp File 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_DownKrpFile = async function () {
    try { return await $c.data.downFile("http://www.krx.co.kr/servlets/exkrx/util/Download", "", ($c.util.getComponent("dma_DownKrpFileReq") ? $c.util.getComponent("dma_DownKrpFileReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name goURL
 * @description go URL 처리
 * @param {String} flag flag
 * @param {String} isurCd isurCd
 * @param {*} bycorpSeq bycorpSeq
 * @param {*} partcYy partcYy
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goURL = async function (flag, isurCd, bycorpSeq, partcYy) {
    if (flag === 'list') {
        $c.util.getComponent('dma_GoURLReq').set('method', 'searchKrpReport');
        await scwin.tx_fn_GoURL('report.do');
    } else {
        if (flag === 'detail') {
            $c.util.getComponent('dma_GoURLReq').set('method', 'searchKrpReportDetail');
            $c.util.getComponent('dma_GoURLReq').set('isurCd', isurCd);
            $c.util.getComponent('dma_GoURLReq').set('bycorpSeq', bycorpSeq);
            $c.util.getComponent('dma_GoURLReq').set('partcYy', partcYy);
            await scwin.tx_fn_GoURL('report.do');
        }
    }
};

/**
 * @method
 * @name downKrpFile
 * @description down Krp File 처리
 * @param {*} _realName _realName
 * @param {*} _fileName _fileName
 * @param {*} _fileDir _fileDir
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.downKrpFile = async function (_realName, _fileName, _fileDir) {
    $c.util.getComponent('dma_GoURLReq').set('fileName', _fileName);
    $c.util.getComponent('dma_GoURLReq').set('realName', _realName);
    $c.util.getComponent('dma_GoURLReq').set('fileDir', _fileDir);
    await scwin.tx_fn_DownKrpFile();
};
